// One modeled town at a time. Local actions and logical references are never drawn as network packets.
import {modelContext,modelLayout,modelOverview,modelColors} from './k8s-model.js';
export const townProfiles={};
export const connectionColors={...modelColors,logical:0xffd18d,storage:0xb7df92};
const logical=(from,to,title,text,relation='configuration',channel='logical')=>({from,to,title,text,relation,channel,kind:'Logical / local relationship',packet:'No transport port · '+text,transport:null,exchange:null});
function exchange(from,to,title,protocol,port,request,response,channel='traffic'){
 const key=[from,to,title].join(':');const common={relation:'network',channel,kind:protocol+' exchange',transport:{protocol,serverPort:port,initiator:from},exchange:key};
 return [{...common,from,to,title,phase:'request',text:request,packet:`${from} ephemeral → ${to} :${port} · ${protocol}`},{...common,from:to,to:from,title:title+' response',phase:'response',text:response,packet:`${to} :${port} → ${from} ephemeral · same exchange`}];
}
export function installTowns(nodes,flows,scope){
 const find=id=>{const n=nodes.find(n=>n.id===id);if(!n)throw Error('Unknown town resource '+id);return n;};
 const node=(id,label,parent,kind,purpose,input,output,notes,minor=false)=>{const n={id,label,parent,kind,position:[0,.4,0],size:minor?[.32,.16,.32]:[2.3,kind==='router'?.9:kind==='document'?1.6:2.7,1.9],purpose,input,output,notes,command:'',reference:'https://docs.docker.com/',minor};nodes.push(n);return n;};
 const district=(id,label,course,color)=>Object.assign(node(id,label,'environment','platform',`Explore ${label} as a connected system.`,`Reviewed intent and scoped inputs.`,`Resources and evidence consumed by neighboring towns.`,`A visual district groups responsibilities; it is not a packet-forwarding device.`),{district:true,course,color,size:[32,.3,27]});
 const move=(id,parent)=>{find(id).parent=parent;};
 const profile=(root,label,steps,course,context=[])=>{find(root).label=label;find(root).visualLabel=label;const ids=new Set([root,...nodes.filter(n=>{let p=n;while(p.parent){if(p.parent===root)return true;p=find(p.parent);}return false;}).map(n=>n.id),...context,...steps.flatMap(s=>[s.from,s.to])]);const flowId='town-'+root;flows[flowId]={label:label+' · connected model',color:0x76dfff,steps};const belongs=id=>{let n=find(id);while(n){if(n.id===root)return true;n=n.parent?find(n.parent):null;}return false;};const main=[...ids].filter(id=>id!==root&&!find(id).minor);const own=main.filter(belongs),linked=main.filter(id=>!belongs(id));const overview=[root,...main];const layout={[root]:[0,.7,0]};own.forEach((id,i)=>{layout[id]=[-10+(i%4)*6.6,1.35,-8+Math.floor(i/4)*6.5];});linked.forEach((id,i)=>{layout[id]=[22+(i%2)*7,1.35,-8+Math.floor(i/2)*7];});townProfiles[root]={id:root,label,course,flowId,nodeIds:[...ids],overview,layout,linkedIds:linked,colors:connectionColors};return townProfiles[root];};
 // 1. Git: snapshots and reference updates are local; push/fetch have real request/response boundaries.
 profile('git-district','Git & collaboration',[
 logical('developer','git-working','Edit files','The editor changes local files; no network transfer is implied.','local'),logical('git-working','git-index','Stage selected content','git add copies selected content into the index.','local'),logical('git-index','git-commit','Create snapshot','git commit records the staged snapshot and parents locally.','local'),logical('git-commit','git-branch','Advance branch / HEAD','A local reference changes; a branch is not a separate copied server.','ownership'),
 ...exchange('git-working','git','Git push','HTTPS / TCP',443,'The local Git client initiates an authenticated push; branch policy can reject it.','The remote acknowledges or rejects the requested update. SSH :22 is an alternative transport.','delivery'),
 ...exchange('git-fetch','git','Git fetch','HTTPS / TCP',443,'The local client asks for advertised refs and required objects.','The remote returns Git objects; fetch updates remote-tracking refs without merging the working branch.','delivery'),logical('git-fetch','git-merge','Integrate deliberately','Merge/rebase is a separate local action with possible conflicts.','local'),logical('git-commit','git-tag','Tag a revision','A tag names a commit; it does not itself deploy it.','local'),logical('git-commit','git-revert','Review a revert','Revert records an inverse commit; external side effects need separate handling.','local')
 ],'git',['developer']);
 // 2. Docker: default daemon control uses a local Unix socket; registry transfers use HTTPS.
 district('docker-district','Docker & registry','containers',0x69d9f4);
 for(const id of ['registry','docker-build','image-layers','namespaces'])move(id,'docker-district');
 node('docker-cli','Docker CLI','docker-district','client','Translate user commands into Docker Engine API operations.','A command and local context.','Engine API requests.','The illustrated default endpoint is a local Unix socket, not TCP port 2375.');
 node('docker-engine','Docker Engine / daemon','docker-district','server','Manage image, container, volume and network operations.','Engine API operations.','Build/runtime operations and their results.','A configured remote daemon requires a deliberate authenticated transport; the diagram uses a local socket.');
 node('docker-container','Running container','docker-district','container','Run the application process from an image.','Image, command, environment and attached networks/volumes.','Responses, logs and exit status.','A running container differs from its immutable image and shares the host kernel.');
 node('docker-volume','Named volume','docker-district','database','Keep selected data outside the container writable layer.','Mounted file operations.','Stored files across supported container replacement.','A volume is not automatically a backup or a remote storage service.');
 node('docker-network','Docker bridge / published port','docker-district','router','Connect this example container and publish its listener on the host.','Traffic to an explicitly published host port.','Traffic directed to the configured container listener.','Example mapping: host :8080 → container :80. A Dockerfile EXPOSE does not publish a host port.');
 node('docker-health','Container health check','docker-container','feature','Run the configured health command and record its status.','Command exit results.','Healthy/unhealthy observations.','An unhealthy status alone does not imply every deployment tool restarts the container.',true);
 node('docker-cache','Build layer cache','docker-build','feature','Reuse matching build steps.','Instruction and input cache keys.','Reusable layers or a cache miss.','Changing a dependency manifest can invalidate its downstream build steps.',true);
 profile('docker-district','Docker & registry',[
 logical('docker-cli','docker-engine','Engine API / Unix socket','Default example: a local Unix-domain socket; there is no TCP port to draw.','local'),logical('docker-engine','docker-build','Build instructions','The configured builder executes Dockerfile instructions with the selected context.','local'),logical('docker-build','image-layers','Create image layers','The build produces content-addressed image data.','local'),
 ...exchange('docker-engine','registry','Registry pull','HTTPS / TCP',443,'The engine initiates a scoped, authenticated pull.','The registry returns the manifest and required image layers.','images'),
 ...exchange('docker-engine','registry','Registry push','HTTPS / TCP',443,'An authorized build/release client initiates upload of image content.','The registry acknowledges stored content; it does not deploy containers.','images'),
 logical('image-layers','docker-container','Create an instance','Engine/runtime starts a process using the image and declared configuration.','local'),logical('docker-volume','docker-container','Mount files','A declared volume mount supplies files; it is not an extra network hop.','storage','storage'),
 ...exchange('users','docker-network','Published HTTP','HTTP / TCP',8080,'A client connects to the published host listener in this illustrative local setup.','The response returns over the established client connection.'),
 logical('docker-network','docker-container','Host :8080 → container :80','This is a forwarding/mapping boundary, not a separate application process.','configuration')
 ],'containers',['users']);
 // 3. Jenkins: controller scheduling is distinct from agent job execution.
 Object.assign(find('ci'),{label:'Jenkins controller',visualLabel:'Jenkins controller',purpose:'Schedule pipeline work and coordinate agents, credentials and build records.',notes:'Agents execute the illustrated build work. Jenkins is not a Kubernetes runtime or image registry.'});find('runner').label='Jenkins agent';
 profile('delivery-district','Jenkins & CI/CD',[
 ...exchange('git','webhook','Repository event','HTTPS / TCP',443,'The repository hosting service initiates a signed/authenticated event to the configured CI endpoint.','The endpoint acknowledges the event; a build result arrives through its own configured status mechanism.','delivery'),
 logical('webhook','ci','Schedule a pipeline','The event selects an authorized job and exact source revision.','control','control'),logical('ci','runner','Dispatch agent work','The controller/agent channel carries job control. Inbound WebSocket over HTTPS and SSH-launched agents are different configurations; no universal port is assumed.','control','control'),
 ...exchange('runner','git','Checkout source','HTTPS / TCP',443,'The agent initiates an authorized fetch of the required revision.','The repository returns source objects.','delivery'),
 logical('runner','unit-tests','Run tests','A job process executes tests on the agent; no network service is implied.','local'),logical('runner','docker-build','Build image','The agent invokes its configured builder. A local Engine socket is one example; a remote builder is a different boundary.','local'),
 ...exchange('runner','registry','Push approved image','HTTPS / TCP',443,'Only an authorized job publishes the approved artifact.','The registry confirms the image content/digest.','images'),logical('unit-tests','release-gate','Evaluate release policy','Approval consumes evidence; it is a workflow decision, not a packet gateway.','configuration'),logical('release-gate','argocd','Approve desired-state change','In this example a reviewed Git desired-state revision is approved. GitOps reconciliation and direct CI deployment are distinct choices.','configuration'),
 ...exchange('argocd','api','Reconcile via API','HTTPS / TCP',6443,'The reconciler initiates authenticated Kubernetes API operations; managed endpoint ports can differ.','The API returns operation status; controllers reconcile asynchronously.','control')
 ],'cicd',['git','docker-build','registry','api']);
 // 4. Ansible: inventory/playbooks are input files; SSH is initiated by the control machine.
 district('ansible-district','Ansible configuration','configuration',0xd8a3c9);move('ansible','ansible-district');
 node('ansible-inventory','Inventory & variables','ansible-district','document','Describe intended managed hosts and scoped variables.','Reviewed host/group definitions.','Host selection and connection settings.','An inventory is data, not a host discovery guarantee.');
 node('ansible-playbook','Playbook & roles','ansible-district','document','Declare configuration tasks and handlers.','Reviewed task definitions.','A selected task sequence.','Idempotence depends on modules and task design.');
 for(const suffix of ['a','b'])node('managed-'+suffix,'Managed Linux host '+suffix.toUpperCase(),'ansible-district','server','Apply authorized configuration tasks on a managed host.','SSH-authenticated commands/modules in this example.','Task results and changed/failed status.','The remote user and privilege escalation must be deliberately scoped.');
 profile('ansible-district','Ansible configuration',[
 logical('ansible-inventory','ansible','Read inventory','Select hosts and connection parameters locally.','local'),logical('ansible-playbook','ansible','Read tasks / roles','Ansible loads reviewed definitions on the control machine.','local'),
 ...exchange('ansible','managed-a','SSH task execution','SSH / TCP',22,'The control machine initiates SSH to host A using configured identity.','Module output and changed/failed results return over the authorized session.','control'),
 ...exchange('ansible','managed-b','SSH task execution','SSH / TCP',22,'The control machine initiates SSH to host B.','The host returns task results; a green task result still requires application validation.','control'),logical('ansible','monitoring','Verify configured service','Observe actual service/user behavior after the change. This is a verification responsibility, not a mandatory Ansible→Grafana connection.','configuration')
 ],'configuration',['monitoring']);
 // The remaining towns are added below in the same explicit build order.
 // 5. AWS: public entry, private data and provider control remain separate.
 profile('cloud-district','AWS cloud',[
 ...exchange('users','aws-route53','DNS lookup','DNS / UDP',53,'The client resolver asks for the configured name. This arrow summarizes recursive resolution, not HTTP forwarding.','DNS returns an alias/address answer; the client subsequently opens a separate connection.'),
 ...exchange('users','aws-alb','Public application request','HTTPS / TCP',443,'The client starts TLS to the configured public ALB listener.','The listener returns the application response.'),
 ...exchange('aws-alb','compute','Target application connection','HTTP / TCP',8080,'Example ALB target group: a separate backend connection to a healthy target on :8080.','The target returns its response to the ALB.'),
 ...exchange('compute','aws-rds','Private database query','PostgreSQL / TCP',5432,'An allowed application connects to its private database endpoint. TLS and database identity must be configured.','The database returns rows or an error.'),
 ...exchange('compute','aws-s3','Object API','HTTPS / TCP',443,'The workload initiates an authorized object API request through its configured route or endpoint.','S3 returns the object/result; a bucket does not execute application code by itself.'),
 logical('aws-sg','compute','Stateful traffic policy','A security group evaluates traffic at attached interfaces. It is not an extra application server or proxy hop.'),logical('aws-vpc','compute','Subnet / route placement','VPC and subnet placement determines routing context; internet access is not automatic.'),logical('cloud-identity','compute','Scoped workload identity','IAM authorization and network reachability are separate requirements.'),logical('aws-nat','compute','Optional outbound translation','A NAT gateway supports routed outbound IPv4 initiation from private workloads, not unsolicited inbound access.'),logical('aws-eks','api','Managed Kubernetes boundary','EKS manages its control plane; workload scheduling and worker networking remain Kubernetes responsibilities.','ownership')
 ],'cloud',['users','api']);
 // 6. Networking: resolve first; TLS and backend forwarding are different connections.
 profile('network-district','Networking & traffic',[
 ...exchange('users','public-dns','Resolve hostname','DNS / UDP',53,'Illustrative resolver request for the service name; DNS can also use TCP or encrypted transports.','The resolver returns DNS records, not the website content.'),
 ...exchange('users','load-balancer','TLS application request','HTTPS / TCP',443,'The client connects to the resolved listener and validates the server certificate.','An application response returns on that connection.'),
 ...exchange('load-balancer','ingress','Configured backend listener','HTTP / TCP',80,'This example terminates public TLS at the load balancer and uses a private HTTP backend. Re-encryption is a separate configuration.','The ingress backend returns its HTTP response.'),
 logical('tls','load-balancer','Listener certificate','Certificate, names, validity and trust configure TLS termination; a certificate is not a packet hop.'),logical('route-table','vpc','Route lookup','Longest-prefix routes select a next hop within the routing context; a route does not grant authorization.'),logical('firewall','load-balancer','Allow only intended traffic','Policy evaluates traffic; security group state and stateless ACL return rules differ.'),logical('nat','vpc','Outbound source translation','Private outbound IPv4 may use NAT when routes require it; NAT does not provide an inbound application endpoint.'),logical('cdn','load-balancer','Optional edge / origin','A configured CDN may cache content and initiate an origin request on a miss. This is an alternative front door, not a required DNS hop.')
 ],'networking',['ingress']);
 // 7. Security: evidence and identity references are not packet gateways.
 profile('security-district','Security & identity',[
 logical('gitleaks','release-gate','Secret findings','A configured job inspects source and reports exposed credentials; findings require revocation/remediation.'),logical('sast','release-gate','Static analysis evidence','Analyze code for configured patterns; a passing scan does not prove the application is safe.'),logical('sca','sbom','Dependency inventory','Record dependencies and their versions; the SBOM is evidence, not a firewall.'),logical('trivy','release-gate','Image vulnerability evidence','Scan the chosen digest and evaluate findings against reviewed policy.'),logical('sbom','release-gate','Review supply chain','Policy consumes provenance and component evidence before release.'),logical('iam-city','vault-city','Authorize secret access','Identity and policy control allowed actions; identity itself does not grant a network route.'),
 ...exchange('app-a','vault-city','Read authorized secret','HTTPS / TCP',8200,'Illustrative TLS-enabled Vault listener :8200. The workload authenticates and requests only its scoped secret.','Vault returns permitted data or denial; no actual secret is embedded in the model.','control'),
 logical('waf','load-balancer','HTTP filtering association','A configured WAF evaluates supported HTTP requests at its associated endpoint; this is not an extra universal TCP proxy.')
 ],'devsecops',['release-gate','app-a','load-balancer']);
 // 8. Terraform: reviewed configuration → plan → approved provider calls → state.
 profile('iac-district','Terraform infrastructure',[
 logical('terraform','tf-plan','Create reviewed plan','The CLI compares configuration, prior state and refreshed remote observations. A plan is not an apply.','local'),logical('tf-plan','policy-code','Evaluate policy','Policy evaluates intended changes and evidence, not user request packets.'),logical('policy-code','tf-apply','Approve exact plan','A review authorizes the selected plan; concurrent state changes can invalidate it.'),
 ...exchange('tf-apply','cloud-api','Provider API operation','HTTPS / TCP',443,'The configured provider initiates authorized cloud API operations. These are infrastructure control requests.','The cloud API returns operation results; some resources need polling to reach readiness.','control'),
 logical('tf-apply','tf-state','Persist resource bindings','State maps resource addresses to remote objects. The backend transport and locking depend on configuration; state may contain sensitive data.','storage','storage'),logical('tf-state','terraform','Read previous bindings','State is not the application database or a complete infrastructure backup.','storage','storage'),logical('helm-city','api','Separate workload packaging','A chart describes Kubernetes resources; package rendering and API application are distinct from Terraform cloud provisioning.','configuration')
 ],'iac',['cloud-api','api']);
 // 9. Data: acknowledgements, replication and business completion are different facts.
 profile('data-district','Data, cache & messaging',[
 ...exchange('app-a','redis','Cache lookup','Redis / TCP',6379,'Example private Redis listener; TLS can be configured on this port. The app requests a cache key.','A value or cache miss returns; a miss is not an error by itself.'),
 ...exchange('app-a','database','Database query','PostgreSQL / TCP',5432,'On a cache miss the application performs an authorized query with appropriate TLS configuration.','Rows or a database error return.'),
 ...exchange('app-a','queue','Publish work','AMQP over TLS / TCP',5671,'Example TLS-enabled broker. A producer publishes with configured confirmation semantics.','A broker confirmation means broker acceptance under that configuration, not completed business work.'),
 ...exchange('consumer','queue','Consume / acknowledge','AMQP over TLS / TCP',5671,'The consumer initiates its broker connection/subscription; after processing, consumer acknowledgement frames travel toward the broker on this session.','The broker sends work deliveries on the established consumer session. Processing must handle retries and duplicates; a delivery is not business completion.'),
 logical('database','db-replica','Configured replication','Replication mode, lag and failover depend on the engine; this summary does not assume a universal port.'),logical('migration','database','Reviewed schema change','A migration requires compatibility, authorization, rollout ordering and recovery planning.'),
 ...exchange('consumer','object-store','Store processing result','HTTPS / TCP',443,'Example S3-compatible object API: the worker initiates an authorized write.','The object service returns a result; application completion and broker acknowledgement must be coordinated.')
 ],'databases',['app-a']);
 // 10. Observability: Prometheus pulls; OTLP clients push; Grafana queries.
 profile('observe-district','Observability & monitoring',[
 ...exchange('prometheus','app-a','Scrape metrics','HTTP / TCP',8080,'Example application /metrics listener :8080. Prometheus initiates each scrape; service discovery only supplies targets.','The target returns metric samples. A failed scrape becomes monitoring evidence.','telemetry'),
 ...exchange('grafana','prometheus','Query metrics','HTTP / TCP',9090,'Example private Prometheus API. Grafana initiates the configured backend query.','Prometheus returns matching time series/query results.','telemetry'),
 ...exchange('app-a','otel','Export traces','OTLP over HTTP / TCP',4318,'The instrumented app initiates an export to the configured collector endpoint. TLS and identity are deployment choices.','The collector acknowledges accepted/rejected export data, not incident resolution.','telemetry'),
 logical('otel','tracing','Configured trace exporter','The collector exports only through configured pipelines; backend protocol/port depends on the chosen tracing system.'),logical('telemetry','loki','Configured log ingestion','A log agent collects and sends selected logs. Transport, labels and retention depend on configuration.'),
 ...exchange('prometheus','alertmanager','Send firing alerts','HTTP / TCP',9093,'Prometheus posts evaluated alerts to the configured Alertmanager API.','Alertmanager acknowledges receipt; routing/grouping and receiver delivery follow independently.','telemetry'),
 logical('alertmanager','oncall','Route notification','An explicitly configured receiver sends notifications; acknowledgement is not automatic repair.')
 ],'observability',['app-a','oncall']);
 // 11. Reliability: humans, evidence, backups and verified recovery.
 profile('reliability-district','Reliability & recovery',[
 logical('slo','monitoring','Measure user outcomes','SLIs and error budgets evaluate defined user journeys over a time window; green infrastructure alone is insufficient.'),logical('alertmanager','oncall','Notify responder','Receiver routing and escalation must be configured. This arrow is a responsibility, not a mandatory host-to-host protocol.'),logical('oncall','incident','Coordinate response','Record impact, establish ownership and choose an evidence-based action.'),logical('incident','rollback-city','Approve compatible rollback','Check application/schema compatibility and external side effects before reverting.'),logical('backup','restore','Select tested recovery point','A backup must be restorable, scoped and verified; replication is not automatically a backup.','storage','storage'),logical('rto-rpo','restore','Recovery targets','RTO and RPO guide recovery-time/data-loss objectives; the diagram cannot guarantee them.'),logical('restore','database','Restore and validate','An authorized restore uses the selected engine/runbook. Validate integrity and user behavior before returning service.'),logical('rollback-city','api','Apply reviewed recovery intent','A recovery workflow may use an authenticated API client; this policy summary does not pretend to be that transport.'),logical('cost','slo','Review capacity tradeoffs','Cost changes need user-outcome and capacity evidence, not only a cheaper resource count.')
 ],'sre',['monitoring','alertmanager','database','api']);
 // 12. Linux: a host is processes, files, isolation and permissions, not just a server icon.
 profile('linux-district','Linux & host foundations',[
 logical('shell','linux-host','Execute authorized commands','The example shell runs locally on this host. Remote access would require its own authenticated connection.','local'),logical('linux-host','process','Schedule a process','The kernel schedules processes and mediates system calls.','local'),logical('process','filesystem','Read / write files','Permissions, mounts and the selected filesystem govern file operations.','local'),logical('namespaces','process','Isolation context','Namespaces isolate views; cgroups constrain/account resources. Neither creates a separate guest kernel.','configuration'),logical('linux-host','docker-container','Shared host kernel','A Linux container process uses the host kernel while configured namespaces and limits constrain it.','ownership'),logical('process','telemetry','Observe process evidence','Logs, exits and resource metrics need configured collection; observation alone does not restart a failed service.')
 ],'linux',['namespaces','docker-container','telemetry']);
 // Kubernetes retains the accepted hand-arranged architecture, not the generic town grid.
 townProfiles.cluster={id:'cluster',label:'Kubernetes',course:'kubernetes',flowId:'k8s-model',nodeIds:[...nodes.filter(n=>{let p=n;while(p){if(p.id==='cluster')return true;p=p.parent?find(p.parent):null;}return false;}).map(n=>n.id),...modelContext],overview:modelOverview,layout:modelLayout,colors:connectionColors};
 // Baseline city coordinates: restored whenever another town is selected.
 const roots=nodes.filter(n=>n.district);roots.forEach((n,i)=>{n.position=[-78+(i%4)*52,.3,-78+Math.floor(i/4)*52];n.size=[32,.25,27];if(n.id!=='cluster')n.visualLabelOffset=[0,2+(i%3)*5,0];if(n.id!=='cluster'){const children=nodes.filter(c=>c.parent===n.id);children.forEach((c,j)=>{c.position=[-11+(j%4)*7, .4,-9+Math.floor(j/4)*6];c.visualScale=Math.min(c.visualScale||1,1);});}});
 // Size platforms around every contained direct resource, including large AWS towns.
 for(const n of roots){if(n.id==='cluster')continue;const children=nodes.filter(c=>c.parent===n.id);n.size[2]=Math.max(27,Math.ceil(children.length/4)*6+7);}
 find('environment').size=[216,.12,216];
 const citySteps=[
 ...exchange('delivery-district','git-district','CI checkout','HTTPS / TCP',443,'Town boundary summary: a CI agent initiates repository access. Click a town to see actual resources.','The Git service returns source objects.','delivery'),
 logical('delivery-district','docker-district','Build through configured builder','Town boundary summary: local Engine socket or explicitly configured remote builder; no universal TCP port.'),
 ...exchange('cluster','docker-district','Pull workload image','HTTPS / TCP',443,'A worker runtime initiates a pull from the registry town. The town platform is not a server.','Registry image content returns to that worker.','images'),
 ...exchange('iac-district','cloud-district','Provision cloud resources','HTTPS / TCP',443,'A Terraform provider initiates authorized cloud API requests.','AWS returns operation results.','control'),
 ...exchange('ansible-district','linux-district','Configure managed hosts','SSH / TCP',22,'An Ansible control machine initiates SSH to managed hosts.','Managed hosts return task results.','control'),
 ...exchange('network-district','cluster','Application ingress','HTTP / TCP',80,'The networking town load balancer initiates the configured private HTTP :80 backend connection to the cluster ingress. Public TLS :443 terminates at that load balancer in this example.','The application response returns through the configured entry path.'),
 ...exchange('observe-district','cluster','Scrape workload metrics','HTTP / TCP',8080,'Example: Prometheus initiates a scrape to the configured application metrics endpoint.','The target returns samples.','telemetry'),
 ...exchange('cluster','data-district','Private data query','PostgreSQL / TCP',5432,'The application initiates an authorized database connection; TLS and routes must be configured.','The database returns rows/results.'),
 logical('security-district','delivery-district','Review release evidence','Identity, vulnerability and provenance policy constrain releases; this is not a network gateway.'),logical('reliability-district','cluster','Review and verify recovery','Responders select compatible recovery actions and verify user outcomes; this summary is not a repair packet.')
 ];
 townProfiles.environment={id:'environment',label:'Complete DevOps city',flowId:'town-environment',nodeIds:nodes.map(n=>n.id),overview:roots.map(n=>n.id),layout:null,colors:connectionColors};flows['town-environment']={label:'City · town boundary connections',color:0x76dfff,steps:citySteps};
 // Consistent sources and recognizable resource roles; preserve all existing lesson text.
 const sources={'git-district':'https://git-scm.com/docs','docker-district':'https://docs.docker.com/','delivery-district':'https://www.jenkins.io/doc/','ansible-district':'https://docs.ansible.com/','cloud-district':'https://docs.aws.amazon.com/','network-district':'https://docs.aws.amazon.com/vpc/','security-district':'https://owasp.org/www-project-devsecops-guideline/','iac-district':'https://developer.hashicorp.com/terraform/docs','data-district':'https://www.postgresql.org/docs/','observe-district':'https://prometheus.io/docs/introduction/overview/','reliability-district':'https://sre.google/books/','linux-district':'https://www.kernel.org/doc/html/latest/'};
 for(const n of nodes){let p=n;while(p.parent&&p.parent!=='environment')p=find(p.parent);if(sources[p.id]&&n.reference==='https://docs.docker.com/')n.reference=sources[p.id];if(!n.district&&p.id!=='cluster'&&!n.minor){n.visualRole=n.kind;n.visualTint=p.color||0x84cce8;}}
 scope.included.push('Thirteen connected town models: Kubernetes, Git, Docker, Jenkins, Ansible, AWS, networking, security, Terraform, data, observability, reliability and Linux');
 scope.notIncluded.push('Every vendor feature or production topology; ports and transports shown are explicit example configurations, not universal defaults');
}
